<?php use App\Core\Csrf; use App\Helpers\ViewHelper; $checkoutUser = $checkoutUser ?? []; $savedAddresses = $savedAddresses ?? []; ?>
<div class="container page-head"><?php require dirname(__DIR__) . '/partials/breadcrumbs.php'; ?><p class="eyebrow">Mua sắm</p><h1>Thanh toán</h1></div>
<section class="container section form-layout">
    <?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?>
    <?php if ($savedAddresses): ?><label for="saved-address">Chọn địa chỉ đã lưu</label><select id="saved-address"><option value="">Nhập địa chỉ khác</option><?php foreach ($savedAddresses as $savedAddress): ?><option value="<?= (int)$savedAddress['id'] ?>" data-name="<?= ViewHelper::escape($savedAddress['recipient_name']) ?>" data-phone="<?= ViewHelper::escape($savedAddress['phone']) ?>" data-address="<?= ViewHelper::escape($savedAddress['address']) ?>" <?= (int)($selectedAddressId ?? 0) === (int)$savedAddress['id'] ? 'selected' : '' ?>><?= ViewHelper::escape($savedAddress['label']) ?><?= (int)$savedAddress['is_default'] === 1 ? ' (Mặc định)' : '' ?></option><?php endforeach; ?></select><?php endif; ?>
    <?php if (!empty($checkoutUser['address']) || !empty($checkoutUser['phone']) || !empty($checkoutUser['email'])): ?><div class="saved-address-note"><span class="material-symbols-outlined" aria-hidden="true">location_on</span><span>Thông tin nhận hàng đã được điền từ địa chỉ đã lưu. Bạn có thể chỉnh lại trước khi đặt.</span><a href="/account">Quản lý địa chỉ</a></div><?php endif; ?>
    <form class="form-card" method="post" action="/checkout"><?= Csrf::field() ?><label for="name">Họ và tên</label><input id="name" name="shipping_name" type="text" autocomplete="name" value="<?= ViewHelper::escape((string)($checkoutUser['name'] ?? '')) ?>" required><label for="email">Email nhận thông báo</label><input id="email" name="shipping_email" type="email" autocomplete="email" value="<?= ViewHelper::escape((string)($checkoutUser['email'] ?? '')) ?>" required><label for="phone">Số điện thoại</label><input id="phone" name="shipping_phone" type="tel" autocomplete="tel" value="<?= ViewHelper::escape((string)($checkoutUser['phone'] ?? '')) ?>" required><label for="address">Địa chỉ nhận hàng</label><textarea id="address" name="shipping_address" rows="4" autocomplete="street-address" required><?= ViewHelper::escape((string)($checkoutUser['address'] ?? '')) ?></textarea><label for="voucher">Mã giảm giá (nếu có)</label><input id="voucher" name="voucher_code" type="text" maxlength="50" placeholder="Nhập mã voucher" value="<?= ViewHelper::escape((string)($voucherCode ?? '')) ?>"><fieldset class="payment-options"><legend>Phương thức thanh toán</legend><label><input type="radio" name="payment_method" value="cod" <?= ($paymentMethod ?? 'cod') === 'cod' ? 'checked' : '' ?>> Thanh toán khi nhận hàng (COD)</label><label><input type="radio" name="payment_method" value="payos" <?= ($paymentMethod ?? '') === 'payos' ? 'checked' : '' ?>> Chuyển khoản online qua PayOS (VietQR)</label></fieldset><button class="button button-primary" type="submit">Tiếp tục thanh toán</button></form>
</section>
<?php if ($savedAddresses): ?><script>document.getElementById('saved-address')?.addEventListener('change',function(){const option=this.options[this.selectedIndex];if(!this.value)return;document.getElementById('name').value=option.dataset.name||'';document.getElementById('phone').value=option.dataset.phone||'';document.getElementById('address').value=option.dataset.address||'';});</script><?php endif; ?>
